package dev.zomboid.remains;
import dev.zomboid.remains.delivery.Reflect;import java.util.*;
/** Final pass after all death providers and after scavenging bonuses. Never applies to player Corpse entities. */
public final class LootFinish15{
 public static boolean mutant(boolean original,Object event){if(original)return true;Object entity=Reflect.call(event,"getEntity");String id=Reflect.call(Reflect.get(Reflect.type("net.minecraft.core.registries.BuiltInRegistries"),"ENTITY_TYPE"),"getKey",Reflect.call(entity,"getType")).toString();return id.startsWith("mutants_l4d2:");}
 public static String family(Object stack){String id=Reflect.call(Reflect.get(Reflect.type("net.minecraft.core.registries.BuiltInRegistries"),"ITEM"),"getKey",Reflect.call(stack,"getItem")).toString().toLowerCase(Locale.ROOT);if(id.equals("lrtactical:melee"))try{Object api=Reflect.call(Reflect.type("me.xjqsh.lrtactical.api.item.IMeleeWeapon"),"of",stack);if(api!=null)id=Reflect.call(api,"getId",stack).toString().toLowerCase(Locale.ROOT);}catch(IllegalStateException optionalMissing){}String n=id.substring(id.indexOf(':')+1);for(String type:new String[]{"pickaxe","shovel","hoe","axe","shears","fishing_rod","flint_and_steel","brush","wrench","screwdriver","crowbar","hammer","saw"})if(n.equals(type)||n.endsWith("_"+type)||n.startsWith(type+"_"))return type;return null;}
 public static Object markNpc(Object corpse){Reflect.set(corpse,"lootOwned15",true);return corpse;}
 public static void write(Object corpse,Object tag){Reflect.call(tag,"putBoolean","LootFinal15",Reflect.get(corpse,"lootFinal15"));Reflect.call(tag,"putBoolean","LootOwned15",Reflect.get(corpse,"lootOwned15"));}
 public static void read(Object corpse,Object tag){Reflect.set(corpse,"lootFinal15",Reflect.call(tag,"getBoolean","LootFinal15"));Reflect.set(corpse,"lootOwned15",Reflect.call(tag,"getBoolean","LootOwned15"));}
 public static void finish(Object corpse,Object world,Object event){try{Reflect.call(Reflect.type("dev.zomboid.hordes.CorpseFinish45"),"finish",corpse,world,event);}catch(IllegalStateException e){if(!(e.getCause() instanceof ClassNotFoundException))throw e;}Reflect.set(corpse,"lootFinal15",true);normalize(corpse,world);}
 public static void normalize(Object corpse,Object world){if(Boolean.TRUE.equals(Reflect.get(corpse,"lootOwned15")))return;if(!Boolean.TRUE.equals(Reflect.get(corpse,"lootFinal15"))){try{Reflect.call(Reflect.type("dev.zomboid.hordes.CorpseFinish45"),"repair",corpse,world);}catch(IllegalStateException e){if(!(e.getCause() instanceof ClassNotFoundException))throw e;}Reflect.set(corpse,"lootFinal15",true);}Object inv=Reflect.get(corpse,"inventory");inventory(inv,world);Reflect.set(corpse,"randomized",true);}
 public static void repairOnOpen(Object corpse,Object world){if(!Boolean.TRUE.equals(Reflect.get(corpse,"lootFinal15"))&&!Boolean.TRUE.equals(Reflect.get(corpse,"skeleton")))normalize(corpse,world);}
 public static void inventory(Object inv,Object world){Set<String> tools=new HashSet<>();List<Object> kept=new ArrayList<>();int n=((Number)Reflect.call(inv,"getContainerSize")).intValue();for(int i=0;i<n;i++){Object s=Reflect.call(inv,"getItem",i);if(Boolean.TRUE.equals(Reflect.call(s,"isEmpty")))continue;String f=family(s);if(f!=null){if(!tools.add(f))continue;s=Reflect.call(s,"copy");Reflect.call(s,"setCount",1);}kept.add(s);}
  Object empty=Reflect.get(Reflect.type("net.minecraft.world.item.ItemStack"),"EMPTY");List<Integer> slots=new ArrayList<>();for(int i=0;i<n;i++)slots.add(i);Object random=Reflect.call(world,"getRandom");for(int i=n-1;i>0;i--)Collections.swap(slots,i,((Number)Reflect.call(random,"nextInt",i+1)).intValue());for(int i=0;i<n;i++)Reflect.call(inv,"setItem",i,empty);for(int i=0;i<kept.size();i++)Reflect.call(inv,"setItem",slots.get(i),kept.get(i));Reflect.call(inv,"setChanged");
 }
}
